function captureSourceDraft(){
 if(state.screen!=='entry')return;
 const rendered=$('[name="source-mode"]:checked')?.value,mode=['link','text','steps'].includes(rendered)?rendered:state.sourceMode,draft=state.sourceDrafts[mode];
 if(mode==='link'){const field=$('#tutorial-url');if(typeof field?.value==='string')draft.source_url=field.value;const goal=$('#learning-goal');if(typeof goal?.value==='string')draft.learning_goal=goal.value;const watch=$('#watch-video');if(typeof watch?.checked==='boolean')draft.learning_mode=watch.checked?'visual':'auto';const transcript=$('#link-transcript');if(typeof transcript?.value==='string'&&state.sourceRecovery?.open&&state.sourceRecovery.url===draft.source_url.trim())state.sourceRecovery.text=transcript.value;}
 else{const text=$('#tutorial-text'),reference=$('#reference-url');if(typeof text?.value==='string')draft.source_text=text.value;if(typeof reference?.value==='string')draft.reference_url=reference.value;}
}
function sourcePayload(){
 const draft=state.sourceDrafts[state.sourceMode];
 return state.sourceMode==='link'?{source_url:draft.source_url.trim(),source_text:state.sourceRecovery?.open&&state.sourceRecovery.url===draft.source_url.trim()?state.sourceRecovery.text.trim():'',processing_mode:'ai',learning_mode:draft.learning_mode||'visual',...(draft.learning_goal?.trim()?{learning_goal:draft.learning_goal.trim()}:{})}:{source_url:draft.reference_url.trim(),source_text:draft.source_text.trim(),processing_mode:state.sourceMode==='steps'?'structured_text':'ai'};
}
function changeSourceMode(mode){
 if(!['link','text','steps'].includes(mode)||mode===state.sourceMode)return;
 captureSourceDraft();state.sourceMode=mode;state.error=null;state.libraryActionError=false;render(false);focusControl('source-mode-'+mode);
}
function sourceRecoveryFields(){
 const recovery=state.sourceRecovery;
 if(!recovery||recovery.url!==state.sourceDrafts.link.source_url.trim())return '';
 return `<div id="source-recovery" class="spacer">${recovery.open?`<label for="link-transcript">Paste the transcript or written instructions</label><textarea id="link-transcript" required rows="7" maxlength="24000" aria-describedby="transcript-help" placeholder="Paste the actions taught in the tutorial…">${h(recovery.text)}</textarea><p id="transcript-help" class="field-help">Your link above stays attached to the lesson. On YouTube, expand the video description and look for Show transcript, if available. Include complete instructions, not just the title. Create AI lesson will use the text you paste.</p>`:'<p class="field-help">Automatic access failed. You can continue using the transcript or the post’s complete written instructions.</p><button id="paste-source-transcript" type="button" class="button secondary">Paste transcript instead</button>'}</div>`;
}
function revealSourceTranscript(){
 captureSourceDraft();
 if(!state.sourceRecovery||state.sourceRecovery.url!==state.sourceDrafts.link.source_url.trim())return;
 state.sourceRecovery.open=true;state.error=null;render(false);focusControl('link-transcript');
}
function sourceFields(){
 const mode=state.sourceMode,draft=state.sourceDrafts[mode];
 if(mode==='link')return `${state.config.source_processing?.enabled?'<p class="field-help">Learn from visible demonstrations without a transcript. Video observation identifies actions and results, then creates suggested practice steps. Private or restricted sources may be unavailable.</p>':'<p class="field-help">Automatic video transcription is not connected yet. Only publicly readable captions and descriptions can currently be extracted.</p>'}<label for="tutorial-url">Tutorial link</label><input id="tutorial-url" type="url" required maxlength="2048" placeholder="https://…" value="${h(draft.source_url)}" aria-describedby="source-help"><p id="source-help" class="field-help">Instagram posts/reels, TikTok, YouTube videos/Shorts, X and Facebook posts. Performance analysis uses additional free processing credits; exact notes or hidden techniques may still require a score or teacher. Also supports Instructables, Origami.me, MDN, freeCodeCamp and Adafruit.</p><label class="check-label" for="watch-video"><input id="watch-video" type="checkbox" ${draft.learning_mode!=='auto'?'checked':''}> Learn by watching the video — no transcript needed</label><p class="field-help">Video observation uses 5 free processing credits per started minute. Uncheck to try spoken instructions first. This setting applies to video links.</p><label for="learning-goal">What would you like to learn? (optional)</label><input id="learning-goal" type="text" maxlength="300" placeholder="For example: learn this stitch, dance move, or song" value="${h(draft.learning_goal)}">${sourceRecoveryFields()}`;
 return `<label for="tutorial-text">${mode==='steps'?'Your numbered practice steps':'Instructions or a video transcript'}</label><textarea id="tutorial-text" required rows="6" maxlength="24000" aria-describedby="source-help" placeholder="${mode==='steps'?'1. Describe the first action.\n2. Describe the next action.':'Paste the actual tutorial instructions, including the steps you want to practice.'}">${h(draft.source_text)}</textarea><p id="source-help" class="field-help">${mode==='steps'?'Use 2–18 complete numbered steps, one per line. Each becomes a self-review checkpoint.':'Include at least a few complete instructions (100 characters). AI uses this source to create the lesson.'}</p><details class="reference-field" ${draft.reference_url?'open':''}><summary>Add a source link (optional)</summary><label for="reference-url">Source reference</label><input id="reference-url" type="url" pattern="https://.*" maxlength="2048" placeholder="https://…" value="${h(draft.reference_url)}"><p class="field-help">Saved for reference. Pasted instructions are used to build this lesson.</p></details>`;
}
function filteredExamples(){const query=state.exampleQuery.toLocaleLowerCase().trim();return state.config.examples.filter(example=>(state.exampleCategory==='all'||example.category===state.exampleCategory)&&(!query||(example.title+' '+example.category).toLocaleLowerCase().includes(query)));}
function exampleCards(){const examples=filteredExamples();return examples.length?examples.map(e=>`<button class="example-card" type="button" data-example="${h(e.id)}">${icon(e.category)}<span><small>${h(e.category.toUpperCase())} · ${e.steps} STEPS</small><strong>${h(e.title)}</strong></span><span aria-hidden="true">↗</span></button>`).join(''):'<div class="examples-empty"><h3>No examples match yet.</h3><p>Try another search, choose All skills, or bring your own tutorial above.</p><button id="reset-examples" type="button" class="button secondary small">Clear filters</button></div>';}
function bindExamples(){document.querySelectorAll('[data-example]').forEach(button=>button.addEventListener('click',()=>loadLesson({example_id:button.dataset.example})));$('#reset-examples')?.addEventListener('click',()=>{state.exampleQuery='';state.exampleCategory='all';$('#example-search').value='';$('#example-category').value='all';updateExamples();focusControl('example-search');});}
function updateExamples(){const examples=filteredExamples();$('#example-results').innerHTML=exampleCards();$('#example-count').textContent=examples.length+' free '+(examples.length===1?'example':'examples');bindExamples();}
async function submitSource(){captureSourceDraft();const body=sourcePayload();state.libraryActionError=false;if(state.sourceMode!=='steps'&&!state.config.ai_available){state.error='AI is unavailable right now. Use My numbered steps or choose a free example.';render(false);return;}await loadLesson(body);}

function clearPhoto(){state.report=null;state.feedbackSubmissionId=null;photoRevision++;if(photoURL)URL.revokeObjectURL(photoURL);photoURL=null;state.photo=null;state.feedback=null;state.error=null;}
function stop(){generation++;clearTimeout(timer);state.running=false;state.opening=false;state.saving=false;state.refreshing=false;state.historyBusy=null;state.historyError=null;state.stream?.getTracks().forEach(t=>t.stop());state.stream=null;}
function notifyConfig(){const b=state.config.budget;$('#provider-notice').textContent=`Multi-skill studio · ${state.config.ai_available?'live AI trial':'self-guided practice'}${b?' · $'+b.remaining_usd.toFixed(3)+' public AI allowance left':''} · written examples are free; AI illustrations use the allowance.`;}
async function refreshBudget(){try{state.config.budget=await api('/api/budget',{});notifyConfig();}catch{}}
function sourceLink(){const u=state.lesson.source_url,credit=state.lesson.source_attribution?`<p class="caption spacer">${h(state.lesson.source_attribution)}</p>`:'';if(!u||!/^https:\/\//.test(u))return '<span class="caption">Source: your supplied instructions</span>'+credit;return `<a class="source-link" href="${h(u)}" target="_blank" rel="noopener noreferrer">Open the source ↗</a>`+credit;}
function entry(){const free=state.sourceMode==='steps',aiUnavailable=!free&&!state.config.ai_available;return `<div class="entry-heading"><div class="page-title"><div class="eyebrow"><span class="eyebrow-line"></span> LEARN BY DOING</div><h1>Your skill.<br><em>Your next step.</em></h1><p class="subhead">Build a little confidence, one practice at a time.<br class="desktop-break"> Bring a tutorial for any skill, or try a free example.</p></div><div class="entry-stamp" aria-hidden="true"><span>TRY SOMETHING</span><span class="stamp-flower">✳</span><span>NEW</span></div></div>
${accountPanel()}${librarySection()}
<div class="entry-grid multi-entry"><section class="card card-content start-card"><div class="card-kicker"><span class="section-number">01</span> START SOMETHING NEW</div><h2>Make a practice lesson.</h2><form id="tutorial-form" class="entry-form"><fieldset class="source-modes"><legend>How would you like to start?</legend>${[['link','Tutorial link','AI lesson'],['text','Paste instructions','AI lesson'],['steps','My numbered steps','Free self-review']].map(([value,label,note])=>`<label class="source-mode"><input type="radio" id="source-mode-${value}" name="source-mode" value="${value}" ${state.sourceMode===value?'checked':''}><span><strong>${label}</strong><small>${note}</small></span></label>`).join('')}</fieldset>${sourceFields()}<div class="source-submit-note"><span class="tag">${free?'FREE SELF-REVIEW':'USES AI ALLOWANCE'}</span><p class="caption">${free?'Your steps are kept as written. No content is sent to an AI provider.':'Tutorial content is sent to Meta to create your lesson. Only share content you’re allowed to use.'}</p></div>${aiUnavailable?'<p class="field-help">AI is unavailable in this preview. Choose My numbered steps or a free example.</p>':''}<button class="button primary wide spacer" type="submit" ${aiUnavailable?'disabled':''}>${free?'Use my steps':'Create AI lesson'} <span aria-hidden="true">→</span></button>${state.error&&!state.libraryActionError?errorBox(state.error):''}</form></section><aside class="stack"><section class="card card-content inspiration-card"><div class="eyebrow">A SPACE FOR MANY SKILLS</div><div class="skill-mosaic" aria-hidden="true"><span class="mosaic-draw">✎</span><span class="mosaic-craft">⌁</span><span class="mosaic-music">♫</span><span class="mosaic-build">◇</span></div><h2>Small steps.<br> More possibilities.</h2><p class="caption spacer">The lesson follows your source, with its own materials, instructions and checkpoints. Photo feedback checks visible details. Listening, knowledge and hidden qualities need self-review.</p><a class="source-link spacer" href="#examples-section">Explore free examples ↓</a></section>${state.saved&&!state.saved.session?'<section class="card card-content"><h3>Earlier device-only practice</h3><p class="caption spacer">Open it to start a new saved practice. Earlier device-only ticks are kept separate from verified progress.</p><button id="resume" class="button secondary wide spacer">Open earlier practice →</button></section>':''}</aside></div>
<section id="examples-section" class="examples-section" aria-labelledby="examples-heading"><div class="split"><div><div class="eyebrow">MAKE A LITTLE TIME TO TRY</div><h2 id="examples-heading">Find your next practice.</h2></div><span class="caption">Free written examples · AI illustrations use the allowance</span></div><div class="example-discovery"><div><label for="example-search">Find a free example</label><input id="example-search" type="search" maxlength="120" placeholder="Search a skill or lesson…" value="${h(state.exampleQuery)}"></div><div><label for="example-category">Skill</label><select id="example-category"><option value="all">All skills</option>${[...new Set(state.config.examples.map(e=>e.category))].sort().map(category=>`<option value="${h(category)}" ${state.exampleCategory===category?'selected':''}>${h(category[0].toUpperCase()+category.slice(1))}</option>`).join('')}</select></div></div><p id="example-count" class="caption" role="status">${filteredExamples().length} free ${filteredExamples().length===1?'example':'examples'}</p><div id="example-results" class="example-grid">${exampleCards()}</div></section>`;}

function errorBox(message){return `<div class="feedback error" role="alert"><div class="feedback-heading">Let’s try another way.</div><p>${h(message)}</p></div>`;}
function processing(){const copy={
 source:['Reading your tutorial.','Reading the tutorial or observing the demonstration. Longer analyses continue as a saved processing job.','Extraction uses the connected free allowance. Creating the lesson uses the app’s AI allowance. Leaving this screen does not cancel a source job already started.','Back to my instructions'],
 ai:['Turning instructions into steps.','Finding the materials, ordered actions and useful checkpoints in your source.','An AI request already sent may finish and use the trial allowance.','Back to my instructions'],
 free:['Preparing your numbered steps.','Keeping your instructions in order and opening a practice session.','Numbered-step mode uses no AI credits.','Back to my instructions'],
 example:['Opening your example.','Loading the lesson and creating a saved practice session.','The written example is free. AI target illustrations use the shared AI allowance.','Back to practice studio'],
 resume:['Opening saved practice.','Loading your lesson and saved checkpoints from the server.','Resuming practice does not send a new AI request.','Back to practice studio'],
 restart:['Starting a fresh practice.','Creating a new session for this lesson. Your earlier record stays saved.','Starting another session uses no AI credits.','Back to practice studio']
 }[state.operation]||['Opening your practice.','Preparing your lesson and saved progress.','','Back to practice studio'];return `<section class="card loading-state" aria-busy="true"><span class="spinner" aria-hidden="true"></span><div class="eyebrow">YOUR NEXT PRACTICE</div><h1>${h(copy[0])}</h1><p>${h(copy[1])}</p><button id="cancel-loading" class="button secondary spacer">${h(copy[3])}</button><p class="caption spacer">${h(copy[2])}</p></section>`;}

function lessonContext(){return state.lesson.lesson_type==='demonstration_practice'?'Suggested practice inspired by the demonstrated skill. The exercises add beginner coaching; observed video evidence is shown separately.':state.lesson.steps.length+' practical checkpoints, grounded in '+(state.lesson.content_origin==='user_provided_text'?'your supplied instructions':state.lesson.content_origin==='fetched_html'?'the linked tutorial':'the supplied source')+'. Follow the source when a detail needs explanation.';}
function observationLink(reference){
 if(reference?.kind!=='ai_video_observation'||!Number.isFinite(reference.timestamp_seconds)||!state.lesson.source_url)return '';
 try{const url=new URL(state.lesson.source_url);if(!['www.youtube.com','youtube.com','youtu.be'].includes(url.hostname))return '';url.searchParams.set('t',Math.floor(reference.timestamp_seconds)+'s');return `<a class="source-link spacer" href="${h(url.href)}" target="_blank" rel="noopener noreferrer">Watch the referenced moment (${Math.floor(reference.timestamp_seconds/60)}:${String(Math.floor(reference.timestamp_seconds%60)).padStart(2,'0')}) ↗</a>`;}catch{return '';}
}
function overview(){return `<div class="page-title"><div class="eyebrow">YOUR LESSON IS READY · ${h(state.lesson.category.toUpperCase())}</div><h1>${h(title())}</h1><p class="subhead">${h(lessonContext())}</p></div><div class="practice-grid"><section class="card card-content"><div class="split"><h2>Your path, step by step.</h2><span class="tag">${state.lesson.steps.length} CHECKPOINTS</span></div><ol class="overview-list">${state.lesson.steps.map((s,i)=>`<li><span class="step-number">${i+1}</span><div><strong>${h(s.title||s.instructions)}</strong><p>${h(s.expected_visual_result)}</p><span class="checkpoint-kind">${s.photo_assessable===false?'Self-review checkpoint':'Photo checkpoint'}</span></div></li>`).join('')}</ol></section><aside class="stack"><section class="card card-content"><div class="lesson-category">${icon(state.lesson.category)}<span class="tag">${h(state.lesson.category)}</span></div><h2 class="spacer">Bring to the table.</h2>${state.lesson.materials.length?`<ul class="plain-list">${state.lesson.materials.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:'<p class="caption spacer">No separate materials list was extracted. Check your source before starting.</p>'}${state.lesson.difficulty?`<p class="caption spacer">Difficulty: ${h(state.lesson.difficulty)}</p>`:''}<div class="soft-divider"></div>${sourceLink()}${state.lesson.practice_restrictions?.length?`<div class="limit-note">${state.lesson.practice_restrictions.map(h).join(' ')}</div>`:''}<button id="begin" class="button primary wide spacer">${completed()?"Continue practicing":"Start practicing"} →</button></section></aside></div>`;}
function feedback(value){const names={pass:'The visible details match.',retry:'One small adjustment.',uncertain:'Let’s get a clearer look.'};return `<section id="assessment-feedback" tabindex="-1" class="feedback ${value.result}" role="status"><div class="feedback-heading">${h(names[value.result])}</div><p>${h(value.feedback)}</p><ul>${[...value.corrections,...value.requested_evidence].map(x=>`<li>${h(x)}</li>`).join('')}</ul><details><summary>Evidence and limits</summary>${value.criteria.map(c=>`<p><strong>${h(c.criterion)} · ${h(c.status)}</strong><br>${h(c.evidence)}</p>`).join('')}<p class="caption">${h(value.provider)} · ${h(value.model)} · ${Math.round(value.latency_ms)} ms<br>${h(value.safety_notice)}</p></details>${value.result==='pass'&&state.mode==='photo'?`<button id="next" class="button primary wide spacer">${state.index===state.lesson.steps.length-1?'Finish practice':'Continue to the next step'} →</button>`:''}</section>`;}
function practice(){const s=step(),total=state.lesson.steps.length;return `<div class="practice-toolbar"><button id="lesson-overview" class="button quiet small">← Lesson overview</button><span class="caption" role="status">${completed()} of ${total} checkpoints practiced</span>${refreshControl()}</div>${checkpointChooser()}<div class="title-row"><div><div class="step-meta">${h(state.lesson.category.toUpperCase())} / STEP ${state.index+1} OF ${total}</div><h1 class="step-title">${h(s.title||'Practice step '+(state.index+1))}</h1></div><div class="mode-switch" role="group" aria-label="Learning mode"><button id="photo-mode" aria-pressed="${state.mode==='photo'}">${s.photo_assessable===false?'Self-review':'Photo checkpoints'}</button><button id="live-mode" aria-pressed="${state.mode==='live'}" ${s.photo_assessable===false?'disabled':''}>Live camera</button></div></div><progress class="sr-only" max="${total}" value="${completed()}" aria-label="${completed()} of ${total} checkpoints practiced"></progress><div class="checkpoint-rail" aria-hidden="true">${state.lesson.steps.map((_,i)=>`<span class="${state.done[i]?'reached':i===state.index?'current':''}"></span>`).join('')}</div><div class="practice-grid"><section class="card instruction-card"><div class="target-card"><span class="eyebrow">YOUR TARGET</span>${targetIllustration()}<p>${h(s.expected_visual_result)}</p><small>${state.lesson.lesson_type==='demonstration_practice'?'Suggested practice target · self-review where sound or timing matters':'Illustrated practice target · follow the written instructions'}</small></div><div class="card-content"><div class="eyebrow">LET’S TRY IT</div><p class="instruction">${h(s.instructions)}</p>${s.assessment_criteria?.length?`<div class="soft-divider"></div><h3>Look for these details</h3>${s.assessment_criteria.map(c=>`<p class="check-row"><span class="check-icon" aria-hidden="true">✓</span>${h(c)}</p>`).join('')}`:''}<div class="limit-note">${s.visual_limits.map(h).join(' ')}</div>${sourceLink()}${s.source_reference?.quote?`<details class="source-quote"><summary>${s.source_reference.kind==='ai_video_observation'?'Read the AI-observed evidence':'Read the source passage'}</summary><blockquote>${h(s.source_reference.quote)}</blockquote>${observationLink(s.source_reference)}</details>`:''}</div></section>${state.session&&state.serverProgress&&state.serverProgress.current_step_id!==s.id&&!state.feedback?reviewPanel():s.photo_assessable===false?selfPanel():state.mode==='live'?livePanel():photoPanel()}</div>`;}
function selfPanel(){return `<section class="card card-content" ${state.saving?'aria-busy="true"':''}><span class="tag">SELF-REVIEW</span><h2 class="spacer">Practice beyond the picture.</h2><p class="caption spacer">This checkpoint needs listening, thinking or a physical quality a photo can’t establish. Follow the instructions, then acknowledge your practice.</p>${state.error?errorBox(state.error):''}<div class="limit-note">This is your acknowledgement, not an AI pass or a safety certification.</div>${acknowledgement('I’ve practiced this step →')}</section>`;}
function photoPanel(){return `<section class="card card-content" ${state.busy?'aria-busy="true"':''}><div class="split"><h2>Make it. Then show it.</h2><span class="tag">PHOTO CHECKPOINT</span></div><p class="caption spacer">Show the required details clearly. Check my work sends your photo to Meta and saves it privately with this practice. Delete saved photos from your practice history.</p><input class="sr-only" id="photo-file" type="file" accept="image/png,image/jpeg,image/webp" tabindex="-1" aria-label="Choose a photo of your work">${state.photo?`<div class="photo-preview"><img src="${h(state.photo.url)}" alt="Your work for this step"><div class="preview-actions"><span>Your selected photo</span><button id="replace-photo" class="button quiet small" ${state.busy||!isCurrentStep()?'disabled':''}>Replace</button></div></div>`:'<button id="upload-zone" class="upload-zone"><span class="upload-icon" aria-hidden="true">↑</span><strong>Add a photo of your work</strong><small>Choose a file or drop it here</small></button>'}<p class="caption">PNG, JPEG or WebP · 5 MiB maximum</p><button id="check-photo" class="button primary wide spacer" ${!state.photo||state.busy||state.refreshing||!isCurrentStep()?'disabled':''}>${!isCurrentStep()?'Checkpoint saved':state.saving?'Saving practice…':state.busy?'Checking the visible details…':'Check my work'}</button>${state.busy?`<p class="loading-feedback" role="status"><span class="spinner" aria-hidden="true"></span>${state.saving?'Saving your practice record…':'Looking at this step’s criteria…'}</p>`:''}${state.error?errorBox(state.error):''}${state.feedback?feedback(state.feedback):''}${isCurrentStep()?acknowledgement('Continue as self-practice, without photo verification','button quiet wide spacer'):''}</section>`;}
function livePanel(){return `<section class="card card-content"><h2>A little guidance as you go.</h2><p class="caption spacer">Opening the camera shows a local preview. Start feedback sends sampled still frames to Meta and uses the shared trial allowance.</p><div class="camera-view"><video id="camera-video" autoplay playsinline muted></video>${!state.stream?'<p class="camera-placeholder">Your practice space<br>Open your camera when you’re ready.</p>':''}<span class="camera-label">${state.running?'SAMPLED AI FEEDBACK':'LOCAL CAMERA PREVIEW'}</span></div><div class="cluster spacer"><button id="open-camera" class="button secondary" ${state.stream||state.opening?'disabled':''}>${state.opening?'Opening camera…':'Open camera'}</button><button id="switch-camera" class="button secondary" ${!state.stream||state.opening||state.cameraDevices.length<2?'disabled':''}>Switch camera</button><button id="start-live" class="button primary" ${!state.stream||state.running?'disabled':''}>Start feedback</button><button id="stop-live" class="button secondary">Stop</button></div><p class="caption spacer">One request at a time. Frames are dropped while a request is in flight. Feedback never advances the step automatically. Switching cameras stops feedback; start it again when ready.</p>${state.error?errorBox(state.error):''}${state.feedback?feedback(state.feedback):''}${acknowledgement('Finish this checkpoint as self-practice →','button quiet wide spacer')}</section>`;}
function completion(){return `${state.error?errorBox(state.error):''}<section class="completion"><div class="completion-art" aria-hidden="true">✳</div><div class="eyebrow">SOMETHING PRACTICED BY YOU</div><h1 class="spacer">A little more familiar.<br>A step further along.</h1><p class="subhead">${h(title())}</p><div class="completion-stats"><div><strong>${state.done.filter(x=>x?.kind==='photo').length}</strong><small>photo-supported checkpoints</small></div><div><strong>${state.done.filter(x=>x?.kind==='self').length}</strong><small>self-acknowledged checkpoints</small></div></div><p class="caption">Progress saved on the server. ${accountUser()?'Your signed-in account keeps access.':'This browser holds your private session access.'} This is not proof of competence or safety.</p><div class="cluster spacer" id="completion-actions"><button id="again" class="button primary">Practice again</button><button id="new-lesson" class="button secondary">Try another skill →</button></div></section>`;}
function render(focus=true){if(!state.config)return;if(state.accountBusy){$('#main').innerHTML='<section class="card card-content" role="status" aria-busy="true">Checking your account before showing saved practice…</section>';$('#lesson-nav').innerHTML='';return;}const active=state.screen==='entry'&&!focus?document.activeElement:null,caret=typeof active?.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null;captureSourceDraft();$('#main').innerHTML=(state.screen!=='entry'?libraryNotice():'')+({entry,processing,overview,step:practice,complete:completion})[state.screen]()+(['step','complete'].includes(state.screen)?`<div id="practice-history">${historyPanel()}</div>`:'')+(state.lesson&&state.session&&['overview','step','complete'].includes(state.screen)?reportPanel():'');$('#lesson-nav').innerHTML=state.lesson&&['overview','step','complete'].includes(state.screen)?`<div class="eyebrow">${h(title())}</div>${state.lesson.steps.map((s,i)=>`<button class="nav-step ${state.done[i]?'done':''}" data-step="${i}" ${state.screen==='step'&&i===state.index?'aria-current="step"':''}><span class="step-number">${state.done[i]?'✓':i+1}</span><span>${h(s.title||'Step '+(i+1))}</span></button>`).join('')}`:'';bind();if(['overview','step'].includes(state.screen))queueMicrotask(loadTargetIllustration);if(state.stream&&$('#camera-video'))$('#camera-video').srcObject=state.stream;if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0);}else if(active?.id&&/^[a-z0-9_-]+$/i.test(active.id)){const next=$('#'+active.id);next?.focus?.({preventScroll:true});if(caret)next?.setSelectionRange?.(...caret);}}
async function useLesson(lesson,epoch=generation){const progress=await window.ShowOncePublic.request('/v1/sessions',{lesson_id:lesson.id,save_to_account:!!accountUser()});if(epoch!==generation)return false;stop();clearPhoto();state.lesson=lesson;state.index=0;state.done=[];state.session={id:progress.session_id,token:progress.access_token};state.history=null;clearHistoryImage();state.pending=null;state.pendingAck=null;applyProgress(progress);state.screen='overview';save();render();return true;}
async function loadLesson(body){if(state.accountBusy||state.accountError){state.error='Check your account connection before starting practice.';render(false);return;}captureSourceDraft();body={...body,save_to_account:!!accountUser()};if(!body.example_id)state.draft={...body};state.operation=body.example_id?'example':body.processing_mode==='structured_text'?'free':body.source_url&&!body.source_text&&state.config.source_processing?.enabled?'source':'ai';const epoch=++generation;state.screen='processing';state.error=null;render();try{let lesson=await window.ShowOncePublic.request('/v1/lessons',body,{timeoutMs:300000});while(lesson.status==='source_processing'){if(epoch!==generation)return;state.operation='source';render(false);await new Promise(resolve=>setTimeout(resolve,Math.min(15000,Math.max(3000,Number(lesson.retry_after_ms)||5000))));if(epoch!==generation)return;lesson=await window.ShowOncePublic.request('/v1/lessons',body,{timeoutMs:300000});}if(epoch!==generation)return;if(await useLesson(lesson,epoch))announce('Your lesson is ready.');}catch(e){if(epoch===generation){state.screen='entry';state.error=e.message;if(!body.example_id&&body.source_url&&!body.source_text&&['transcript_required','source_unavailable','source_redirects','source_too_large','source_too_long','unsupported_source','source_insufficient_content','source_inaccessible','source_transcription_failed'].includes(e.code))state.sourceRecovery={url:body.source_url.trim(),open:false,text:''};render();}}finally{refreshBudget();}}
async function choosePhoto(file){if(!file||state.busy||state.accountBusy||state.accountError)return;const epoch=generation,revision=++photoRevision;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Choose PNG, JPEG or WebP.');if(file.size>5242880)throw new Error('Choose a photo smaller than 5 MiB.');const bytes=new Uint8Array(await file.arrayBuffer());if(epoch!==generation||revision!==photoRevision||state.busy)return;let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));clearPhoto();photoURL=URL.createObjectURL(file);state.photo={url:photoURL,mime:file.type,base64:btoa(binary)};render(false);$('#check-photo')?.focus();}catch(e){if(epoch===generation&&revision===photoRevision){state.error=e.message;render(false);}}}
async function check(){if(state.accountBusy||state.accountError||!state.photo||state.busy||!state.session||!isCurrentStep())return;const epoch=generation;state.busy=true;state.error=null;state.feedback=null;state.feedbackSubmissionId=null;if(!state.pending||state.pending.revision!==photoRevision||state.pending.step_id!==step().id)state.pending={key:crypto.randomUUID(),revision:photoRevision,step_id:step().id};render(false);try{const response=await sessionAPI('submissions',{step_id:step().id,mime_type:state.photo.mime,image_base64:state.photo.base64},{key:state.pending.key});if(epoch!==generation)return;applyProgress(response.progress);if(response.submission.status==='processing'){state.error='Your photo is still being checked. Refresh practice history before retrying.';}else if(response.submission.status==='failed'){state.pending=null;state.error='The previous check failed. You can try this photo again as a new submission.';}else{state.feedback=response.submission.assessment;state.feedbackSubmissionId=response.submission.id;state.pending=null;announce(state.feedback.result+': '+state.feedback.feedback);}}catch(e){if(epoch===generation){state.error=e.message;if(e.status&&e.code!=='finalization_failed')state.pending=null;}}finally{if(epoch===generation){state.busy=false;render(false);($('#next')||$('#assessment-feedback')||$('#check-photo'))?.focus();}refreshBudget();}}
const VERSION=()=>state.lesson?.schema_version||'hashir.ai.v2-proposed';

async function next(kind){if(state.accountBusy||state.accountError)return;if(!state.session){state.error='Open saved practice to reconnect before continuing.';render();return;}if(state.busy)return;stop();state.busy=true;state.saving=true;state.error=null;const epoch=generation;render(false);focusControl('acknowledge');try{if(state.serverProgress.current_step_id===step().id){if(kind==='photo')throw new Error('Refresh your saved progress before continuing.');if(state.pendingAck?.step_id!==step().id)state.pendingAck={step_id:step().id,key:crypto.randomUUID()};const value=await sessionAPI('acknowledgements',{step_id:step().id},{key:state.pendingAck.key});if(epoch!==generation)return;applyProgress(value.progress);}clearPhoto();state.pendingAck=null;state.pending=null;state.mode='photo';applyProgress(state.serverProgress,true);announce(state.screen==='complete'?'All checkpoints practiced and saved.':'Progress saved. Continue with your current checkpoint.');}catch(e){if(epoch===generation)state.error=e.message;}finally{if(epoch===generation){state.busy=false;state.saving=false;render();}}}
async function resumePractice(sessionId){if(state.accountBusy||state.accountError)return;captureSourceDraft();const record=typeof sessionId==='string'?state.library.find(entry=>entry.id===sessionId):null;const saved=record?{session:{id:record.id,token:record.token}}:restore(state.saved);if(!saved)return;state.operation='resume';const epoch=++generation;state.error=null;state.libraryActionError=false;state.screen='processing';render();try{if(!saved.session){if(await useLesson(saved.lesson,epoch))announce('Started a server-backed practice. The old device-only record has not been counted as verified progress.');return;}const session=saved.session;const progress=await window.ShowOncePublic.request('/v1/sessions/'+session.id,undefined,{token:session.token,method:'GET'});const lesson=await window.ShowOncePublic.request('/v1/lessons/'+progress.lesson_id,undefined,{method:'GET',token:session.token});if(epoch!==generation)return;clearHistoryImage();Object.assign(state,{lesson,session,mode:'photo',busy:false,history:null,historyImage:null,historyImageId:null,feedback:null,pending:null,pendingAck:null});applyProgress(progress,true);render();}catch(e){if(epoch===generation){state.screen='entry';state.error=e.message;state.libraryActionError=!!record;render();}}}

async function restartPractice(){if(state.accountBusy||state.accountError)return;stop();const epoch=generation;state.operation='restart';state.screen='processing';state.error=null;render();try{await useLesson(state.lesson,epoch);}catch(e){if(epoch===generation){state.error=e.message;state.screen='complete';render();}}}

async function openCamera(deviceID=null){if(state.accountBusy||state.accountError||state.stream||state.opening)return;const epoch=generation;state.opening=true;state.error=null;render(false);try{const stream=await navigator.mediaDevices.getUserMedia({video:deviceID?{deviceId:{exact:deviceID}}:{facingMode:'environment'},audio:false});if(epoch!==generation||state.screen!=='step'||state.mode!=='live'){stream.getTracks().forEach(t=>t.stop());return;}state.stream=stream;state.cameraDeviceId=stream.getVideoTracks()[0]?.getSettings?.().deviceId||deviceID;stream.getVideoTracks().forEach(t=>t.addEventListener('ended',()=>{if(state.stream===stream){stop();state.feedback=null;state.error='Camera disconnected. Open it again or use a photo.';render(false);}}));try{const devices=await navigator.mediaDevices.enumerateDevices?.();if(epoch===generation&&state.stream===stream)state.cameraDevices=(devices||[]).filter(device=>device.kind==='videoinput'&&device.deviceId);}catch{if(epoch===generation)state.cameraDevices=[];}}catch{if(epoch===generation)state.error='Camera access was unavailable. Use photo checkpoints or self-practice instead.';}finally{if(epoch===generation){state.opening=false;render(false);}}}
async function switchCamera(){if(state.accountBusy||state.accountError||state.opening||!state.stream||state.cameraDevices.length<2)return;const devices=state.cameraDevices,index=devices.findIndex(device=>device.deviceId===state.cameraDeviceId),next=devices[(index+1)%devices.length];stop();state.feedback=null;state.feedbackSubmissionId=null;state.cameraDeviceId=next.deviceId;await openCamera(next.deviceId);if(state.stream)announce('Camera switched. Start feedback when ready.');}
async function startLive(){if(state.accountBusy||state.accountError||!state.stream||state.running)return;state.running=true;state.historyBusy=null;state.historyError=null;const epoch=++generation;render(false);const loop=async()=>{if(epoch!==generation||!state.running)return;const video=$('#camera-video');if(!video?.videoWidth){timer=setTimeout(loop,500);return;}const canvas=document.createElement('canvas');const ratio=Math.min(1,960/video.videoWidth);canvas.width=Math.round(video.videoWidth*ratio);canvas.height=Math.round(video.videoHeight*ratio);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const captured=Date.now();try{const value=await api('/api/assess',{lesson_id:state.lesson.id,step_id:step().id,submission_id:'frame_'+crypto.randomUUID(),mime_type:'image/jpeg',image_base64:canvas.toDataURL('image/jpeg',.8).split(',')[1]});if(epoch===generation&&Date.now()-captured<20000){state.feedback=value;state.error=null;render(false);announce('Frame: '+value.result);}}catch(e){if(epoch===generation){stop();state.feedback=null;state.error=e.message;render(false);}}finally{refreshBudget();if(epoch===generation&&state.running)timer=setTimeout(loop,3000);}};loop();}
function reportPanel(){
 const report=state.report;
 if(!report)return `<button id="report-issue" type="button" class="button quiet small spacer" ${state.busy||state.accountBusy?'disabled':''}>Report a problem with this checkpoint</button>`;
 if(report.received)return `<section class="card card-content spacer" role="status"><h2>Report saved for the team</h2><p class="caption spacer">Reference: ${h(report.received)}</p><button id="cancel-report" class="button secondary small spacer">Close</button></section>`;
 return `<section class="card card-content spacer" id="issue-report" ${report.busy?'aria-busy="true"':''}><h2>Report a problem</h2><p class="caption spacer">${h(report.stepTitle)}. This sends the checkpoint and ${report.submissionID||report.cameraID?'selected feedback':'your description'} to the team. Photos are not included.</p><form id="issue-form"><label class="field-label spacer" for="report-reason">Issue type</label><select id="report-reason" ${report.sentBody?'disabled':''}>${[['incorrect_instructions','Incorrect instructions'],['ai_feedback','Poor AI feedback'],['broken_source','Broken source link'],['other','Something else']].map(([value,label])=>`<option value="${value}" ${report.reason===value?'selected':''}>${label}</option>`).join('')}</select><label class="field-label spacer" for="report-details">What went wrong? (optional)</label><textarea rows="4" id="report-details" maxlength="2000" ${report.sentBody?'readonly':''}>${h(report.details)}</textarea>${report.error?errorBox(report.error):''}<div class="cluster spacer"><button class="button primary" type="submit" ${report.busy?'disabled':''}>${report.busy?'Saving report…':report.sentBody?'Retry same report':'Send report'}</button><button id="cancel-report" class="button secondary" type="button" ${report.busy?'disabled':''}>Cancel</button></div></form></section>`;
}
function openReport(stepID=null,submissionID=null){
 if(state.busy||state.accountBusy||state.accountError||!state.session)return;
 const current=stepID?state.lesson.steps.find(step=>step.id===stepID):step();if(!current)return;
 const cameraID=!submissionID&&current.id===step().id?state.feedback?.feedback_id:null;
 const savedID=submissionID||(!cameraID&&current.id===step().id?state.feedbackSubmissionId:null);
 stop();state.report={stepID:current.id,stepTitle:current.title||current.instructions,submissionID:savedID||null,cameraID:cameraID||null,key:crypto.randomUUID(),reason:savedID||cameraID?'ai_feedback':'incorrect_instructions',details:'',busy:false,error:null};render(false);focusControl('report-reason');
}
async function sendReport(){
 const report=state.report;if(!report||report.busy||state.accountBusy||state.accountError)return;const epoch=generation,sessionID=state.session.id;
 report.sentBody||={step_id:report.stepID,reason:report.reason,details:report.details,submission_id:report.submissionID,camera_feedback_id:report.cameraID};report.busy=true;report.error=null;render(false);
 try{const value=await sessionAPI('reports',report.sentBody,{key:report.key});if(sameContext(epoch,sessionID)&&state.report===report){report.received=value.id;announce('Report saved for team review.');}}
 catch(error){if(sameContext(epoch,sessionID)&&state.report===report)report.error=error.message;}
 finally{if(sameContext(epoch,sessionID)&&state.report===report){report.busy=false;render(false);}}
}
function home(){captureSourceDraft();stop();clearPhoto();state.screen='entry';state.busy=false;state.error=null;state.libraryActionError=false;loadLibrary();render();}
